import { test, expect } from '@playwright/test';

test.describe('Modal Content Scroll Independent Overflow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should scroll modal content independently when overflowing', async ({ page }) => {
    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Get modal content container
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Set up overflow
    await modalContent.setInputValue('Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.');

    // Verify content overflows
    await expect(modalContent).toHaveValue('Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.');

    // Scroll to bottom
    const scrollBar = page.locator('[data-testid="modal-scrollbar"]');
    await scrollBar.click();

    // Verify content is visible at bottom
    await expect(modalContent).toBeVisible();

    // Scroll to top
    await scrollBar.click();

    // Verify content is visible at top
    await expect(modalContent).toBeVisible();

    // Close modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();
  });

  test('should handle empty modal content gracefully', async ({ page }) => {
    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Get modal content container
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Set up empty content
    await modalContent.setInputValue('');

    // Verify content is empty
    await expect(modalContent).toHaveValue('');

    // Scroll to bottom
    const scrollBar = page.locator('[data-testid="modal-scrollbar"]');
    await scrollBar.click();

    // Verify content is still empty
    await expect(modalContent).toHaveValue('');

    // Close modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();
  });
});
